#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    vector<char> isEvent(q);
    vector<int> key(q);
    vector<long long> ts(q);
    unordered_map<string, int> ids;
    vector<vector<long long>> coords;
    string o, u, c;
    for (int i = 0; i < q; i++) {
        cin >> o >> u >> c >> ts[i];
        auto it = ids.emplace(u + '\x01' + c, (int)coords.size());
        if (it.second) coords.emplace_back();
        key[i] = it.first->second;
        isEvent[i] = o == "EVENT";
        if (isEvent[i]) coords[key[i]].push_back(ts[i]);
    }
    // Coordinates are only positions; frequencies are added while replaying input order.
    vector<vector<int>> bits(coords.size());
    for (size_t k = 0; k < coords.size(); k++) {
        auto &a = coords[k];
        sort(a.begin(), a.end());
        a.erase(unique(a.begin(), a.end()), a.end());
        bits[k].assign(a.size() + 1, 0);
    }
    auto prefix = [](const vector<int> &bit, int i) {
        int total = 0;
        for (; i > 0; i -= i & -i) total += bit[i];
        return total;
    };
    vector<int> out;
    for (int i = 0; i < q; i++) {
        auto &a = coords[key[i]];
        auto &bit = bits[key[i]];
        if (isEvent[i]) {
            int j = lower_bound(a.begin(), a.end(), ts[i]) - a.begin() + 1;
            for (; j < (int)bit.size(); j += j & -j) bit[j]++;
        } else {
            int hi = upper_bound(a.begin(), a.end(), ts[i]) - a.begin();
            int lo = lower_bound(a.begin(), a.end(), ts[i] - 15) - a.begin();
            out.push_back(prefix(bit, hi) - prefix(bit, lo));
        }
    }
    string s = to_string(out.size()) + "\n";
    for (int v : out) s += to_string(v) + "\n";
    cout << s;
}

import java.io.*;
import java.util.*;

public class Main {
    static int lowerBound(long[] a, int len, long x) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int prefix(int[] bit, int i) {
        int total = 0;
        for (; i > 0; i -= i & -i) total += bit[i];
        return total;
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int q = Integer.parseInt(st.nextToken());
        boolean[] isEvent = new boolean[q];
        int[] key = new int[q];
        long[] ts = new long[q];
        HashMap<String, Integer> ids = new HashMap<>();
        int[] eventCount = new int[q];
        for (int i = 0; i < q; i++) {
            String o = st.nextToken(), u = st.nextToken(), c = st.nextToken();
            ts[i] = Long.parseLong(st.nextToken());
            Integer id = ids.get(u + "\u0001" + c);
            if (id == null) {
                id = ids.size();
                ids.put(u + "\u0001" + c, id);
            }
            key[i] = id;
            isEvent[i] = o.equals("EVENT");
            if (isEvent[i]) eventCount[id]++;
        }
        int keys = ids.size();
        long[][] coords = new long[keys][];
        int[] len = new int[keys];
        for (int k = 0; k < keys; k++) coords[k] = new long[eventCount[k]];
        for (int i = 0; i < q; i++)
            if (isEvent[i]) coords[key[i]][len[key[i]]++] = ts[i];
        // Coordinates are only positions; frequencies are added while replaying input order.
        int[][] bits = new int[keys][];
        for (int k = 0; k < keys; k++) {
            long[] a = coords[k];
            Arrays.sort(a);
            int u = 0;
            for (int i = 0; i < a.length; i++)
                if (u == 0 || a[i] != a[u - 1]) a[u++] = a[i];
            len[k] = u;
            bits[k] = new int[u + 1];
        }
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = 0; i < q; i++) {
            long[] a = coords[key[i]];
            int n = len[key[i]];
            int[] bit = bits[key[i]];
            if (isEvent[i]) {
                for (int j = lowerBound(a, n, ts[i]) + 1; j <= n; j += j & -j) bit[j]++;
            } else {
                int hi = lowerBound(a, n, ts[i] + 1), lo = lowerBound(a, n, ts[i] - 15);
                sb.append(prefix(bit, hi) - prefix(bit, lo)).append('\n');
                count++;
            }
        }
        System.out.print(count + "\n" + sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string {
		sc.Scan()
		return sc.Text()
	}
	q, _ := strconv.Atoi(next())
	isEvent := make([]bool, q)
	key := make([]int, q)
	ts := make([]int64, q)
	ids := map[string]int{}
	coords := [][]int64{}
	for i := 0; i < q; i++ {
		o, u, c := next(), next(), next()
		ts[i], _ = strconv.ParseInt(next(), 10, 64)
		k := u + "\x01" + c
		id, ok := ids[k]
		if !ok {
			id = len(coords)
			ids[k] = id
			coords = append(coords, nil)
		}
		key[i] = id
		isEvent[i] = o == "EVENT"
		if isEvent[i] {
			coords[id] = append(coords[id], ts[i])
		}
	}
	// Coordinates are only positions; frequencies are added while replaying input order.
	bits := make([][]int, len(coords))
	for k, a := range coords {
		sort.Slice(a, func(x, y int) bool { return a[x] < a[y] })
		u := 0
		for i := range a {
			if u == 0 || a[i] != a[u-1] {
				a[u] = a[i]
				u++
			}
		}
		coords[k] = a[:u]
		bits[k] = make([]int, u+1)
	}
	prefix := func(bit []int, i int) int {
		total := 0
		for ; i > 0; i -= i & -i {
			total += bit[i]
		}
		return total
	}
	out := []int{}
	for i := 0; i < q; i++ {
		a, bit := coords[key[i]], bits[key[i]]
		lower := func(x int64) int { return sort.Search(len(a), func(j int) bool { return a[j] >= x }) }
		if isEvent[i] {
			for j := lower(ts[i]) + 1; j < len(bit); j += j & -j {
				bit[j]++
			}
		} else {
			out = append(out, prefix(bit, lower(ts[i]+1))-prefix(bit, lower(ts[i]-15)))
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for _, v := range out {
		w.WriteString(strconv.Itoa(v) + "\n")
	}
}
